#include <functional>
struct Op { int offset; int operator()(int x, int y) const { return offset + x + y; } };
extern "C" int replacement() {
  auto b = std::bind(Op{3}, std::placeholders::_1, 4);
  return b(5) == 12 ? 0 : 1;
}

#include <functional>
struct Counter { int value; int operator()(int x) { value += x; return value; } };
extern "C" int replacement() {
  auto b = std::bind(Counter{1}, std::placeholders::_1);
  int first = b(2);
  auto c = b;
  int second = b(3);
  int copied = c(4);
  return first == 3 && second == 6 && copied == 7 && b(0) == 6 && c(0) == 7 ? 0 : 1;
}

#include <functional>
#include <utility>
struct Op {
  int value;
  int operator()(int x) & { return value + x + 1; }
  int operator()(int x) const & { return value + x + 10; }
};
extern "C" int replacement() {
  auto b = std::bind(Op{2}, std::placeholders::_1);
  const auto &c = b;
  int left = b(3);
  int constant = c(3);
  int right = std::move(b)(3);
  return left == 6 && constant == 15 && right == 6 ? 0 : 1;
}

#include <functional>
struct Counter { int value; int operator()(int x) { value += x; return value; } };
extern "C" int replacement() {
  Counter target{1};
  auto b = std::bind(std::ref(target), std::placeholders::_1);
  auto c = b;
  int first = b(2);
  int shared = c(4);
  target.value = 10;
  int live = b(1);
  return first == 3 && shared == 7 && live == 11 && target.value == 11 ? 0 : 1;
}

#include <functional>
extern "C" int replacement() {
  auto add = std::bind(std::plus<int>{}, std::placeholders::_1, 4);
  const auto copied = add;
  auto subtract = std::bind(std::minus<>{}, std::placeholders::_1, 2);
  return add(3) == 7 && copied(6) == 10 && subtract(9) == 7 ? 0 : 1;
}

#include <functional>
struct Counter { int value; int add(int x) { value += x; return value; } };
extern "C" int replacement() {
  Counter target{2};
  auto b = std::bind(&Counter::add, std::ref(target), std::placeholders::_1);
  int first = b(3);
  int second = b(4);
  return first == 5 && second == 9 && target.value == 9 ? 0 : 1;
}

#include <functional>
struct Op { int operator()(int x) const { asm volatile(""); return x; } };
extern "C" int replacement() {
  auto b = std::bind(Op{}, std::placeholders::_1);
  return b(0);
}

#include <functional>
struct Op { int operator()(int x) { return x; } };
extern "C" int replacement() {
  const auto b = std::bind(Op{}, std::placeholders::_1);
  return b(1);
}
